/**
 * Measurement completeness dimensions for graphical progress rings.
 * Defaults to MSME paths; pass pathOverrides / segment for enterprise and observers.
 */

export type MeasurementDimensionId =
  | 'profile'
  | 'bills'
  | 'electricity'
  | 'fuel'
  | 'operations';

export type MeasurementDimension = {
  id: MeasurementDimensionId;
  label: string;
  complete: boolean;
  hint: string;
  path: string;
};

export type MeasurementCompleteness = {
  percent: number;
  completedCount: number;
  totalCount: number;
  dimensions: MeasurementDimension[];
  nextCta: { label: string; path: string } | null;
};

export type MeasurementPathOverrides = Partial<Record<MeasurementDimensionId, string>>;

export type MeasurementCompletenessInput = {
  hasProfile?: boolean;
  hasDocuments?: boolean;
  hasAssessment?: boolean;
  hasWorkflow?: boolean;
  /** True when electricity / grid bills or Scope 2 kg present */
  hasElectricitySignal?: boolean;
  /** True when fuel / diesel / Scope 1 energy kg present */
  hasFuelSignal?: boolean;
  /** Override CTA / chip destinations (enterprise, citizen, etc.) */
  pathOverrides?: MeasurementPathOverrides;
  /** When false, nextCta is always null (admin/support/partner observers). */
  includeCta?: boolean;
};

/** Enterprise workspace path map for the same five measurement dimensions. */
export const ENTERPRISE_MEASUREMENT_PATHS: MeasurementPathOverrides = {
  profile: '/enterprise/profile',
  bills: '/enterprise/data',
  electricity: '/enterprise/workflow',
  fuel: '/enterprise/workflow',
  operations: '/enterprise/workflow',
};

export function deriveMeasurementCompleteness(
  input: MeasurementCompletenessInput
): MeasurementCompleteness {
  const paths = input.pathOverrides || {};
  const dimensions: MeasurementDimension[] = [
    {
      id: 'profile',
      label: 'Company profile',
      complete: Boolean(input.hasProfile),
      hint: 'GST, industry, and contact details',
      path: paths.profile || '/msme-profile',
    },
    {
      id: 'bills',
      label: 'Bills uploaded',
      complete: Boolean(input.hasDocuments),
      hint: 'Electricity, fuel, or purchase invoices',
      path: paths.bills || '/document-upload',
    },
    {
      id: 'electricity',
      label: 'Electricity data',
      complete: Boolean(input.hasElectricitySignal),
      hint: 'Power bills or operations kWh',
      path: paths.electricity || '/operations',
    },
    {
      id: 'fuel',
      label: 'Fuel / vehicles',
      complete: Boolean(input.hasFuelSignal),
      hint: 'Diesel, petrol, or fleet fuel',
      path: paths.fuel || '/operations',
    },
    {
      id: 'operations',
      label: 'Operations map',
      complete: Boolean(input.hasWorkflow) || Boolean(input.hasAssessment),
      hint: 'Sites and main activities',
      path: paths.operations || '/operations',
    },
  ];

  const completedCount = dimensions.filter((d) => d.complete).length;
  const totalCount = dimensions.length;
  const percent = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  const next = dimensions.find((d) => !d.complete) || null;
  const includeCta = input.includeCta !== false;

  return {
    percent,
    completedCount,
    totalCount,
    dimensions,
    nextCta:
      includeCta && next
        ? {
            label:
              next.id === 'bills'
                ? 'Upload next bill'
                : next.id === 'electricity'
                  ? 'Add electricity data'
                  : next.id === 'fuel'
                    ? 'Add fuel data'
                    : next.id === 'profile'
                      ? 'Complete profile'
                      : 'Map operations',
            path: next.path,
          }
        : null,
  };
}

/** Infer electricity/fuel signals from category labels or scope kg. */
export function inferEnergySignals(input: {
  categoryBreakdown?: Array<{ name?: string; category?: string; kg?: number }>;
  scope2Kg?: number;
  scope1Kg?: number;
  powerKwh?: number;
  fuelLiters?: number;
}): { hasElectricitySignal: boolean; hasFuelSignal: boolean } {
  const cats = (input.categoryBreakdown || [])
    .map((row) => String(row.name || row.category || '').toLowerCase())
    .join(' ');
  const hasElectricitySignal = Boolean(
    (Number(input.scope2Kg) || 0) > 0
    || (Number(input.powerKwh) || 0) > 0
    || /electric|power|grid|kwh|discom/.test(cats)
  );
  const hasFuelSignal = Boolean(
    (Number(input.scope1Kg) || 0) > 0
    || (Number(input.fuelLiters) || 0) > 0
    || /fuel|diesel|petrol|cng|lpg|fleet|vehicle/.test(cats)
  );
  return { hasElectricitySignal, hasFuelSignal };
}
