export interface EnterpriseWorkflowSection {
  key: string;
  label: string;
  status: 'pending' | 'in_progress' | 'completed';
  completedAt?: string;
}

export const hasCompletedEnterpriseWorkflow = (
  sections: EnterpriseWorkflowSection[] | undefined | null
): boolean => {
  if (!Array.isArray(sections) || sections.length === 0) {
    return false;
  }
  return sections.every((section) => section.status === 'completed');
};
