import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  FormControl,
  FormControlLabel,
  FormGroup,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  Tab,
  Tabs,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';
import { scrollableTabsSx } from '../../constants/appShellLayout';

type Facility = {
  name: string;
  state: string;
  operationalControl: boolean;
  scope1Sources: string[];
  scope2Sources: string[];
};

type Scope3Category = {
  category: string;
  material: boolean;
  coveragePercent: number;
};

const parseSources = (value: string) =>
  value.split(',').map((s) => s.trim()).filter(Boolean);

const joinSources = (sources: string[] | undefined) => (sources || []).join(', ');

const EnterpriseProfileSection: React.FC = () => {
  const [tab, setTab] = useState(0);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [form, setForm] = useState<Record<string, unknown>>({});
  const [facilities, setFacilities] = useState<Facility[]>([]);
  const [scope3Categories, setScope3Categories] = useState<Scope3Category[]>([]);

  const loadProfile = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [profileRes, templateRes] = await Promise.all([
        ApiService.getEnterpriseProfile(),
        ApiService.getEnterpriseScope3Template().catch(() => null),
      ]);
      const data = profileRes?.data || profileRes;
      if (!data) {
        setError('Enterprise profile not found. Complete registration first.');
        return;
      }
      setForm(data);
      setFacilities(
        Array.isArray(data.facilities) && data.facilities.length > 0
          ? data.facilities
          : [{ name: '', state: '', operationalControl: true, scope1Sources: [], scope2Sources: [] }]
      );
      const templateCategories = templateRes?.data?.categories;
      const existing = data.scope3Materiality?.categories;
      setScope3Categories(
        Array.isArray(existing) && existing.length > 0
          ? existing
          : templateCategories || []
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load profile');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadProfile();
  }, [loadProfile]);

  const saveOrganization = async () => {
    setSaving(true);
    setMessage(null);
    setError(null);
    try {
      const response = await ApiService.updateEnterpriseProfile(form);
      if (!response?.success) {
        throw new Error(response?.message || 'Save failed');
      }
      setMessage('Organization profile saved.');
      await loadProfile();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(false);
    }
  };

  const saveOperations = async () => {
    setSaving(true);
    setMessage(null);
    setError(null);
    try {
      const response = await ApiService.updateEnterpriseOperations({
        facilities,
        scope3Materiality: { categories: scope3Categories },
        consolidationApproach: form.consolidationApproach,
        reportingEntityType: form.reportingEntityType,
        listingStatus: form.listingStatus,
        brsrApplicability: form.brsrApplicability,
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Save failed');
      }
      setMessage('Operations and inventory boundaries saved.');
      await loadProfile();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <Typography>Loading enterprise profile…</Typography>;
  }

  if (error && !form.companyName) {
    return <Alert severity="error">{error}</Alert>;
  }

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise company profile
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Legal entity, regulatory mandates, facilities, and Scope 3 materiality for consolidated reporting.
      </Typography>

      {message && <Alert severity="success" sx={{ mb: 2 }}>{message}</Alert>}
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      <Tabs
        value={tab}
        onChange={(_, v) => setTab(v)}
        variant="scrollable"
        scrollButtons="auto"
        allowScrollButtonsMobile
        sx={{ mb: 2, ...scrollableTabsSx }}
      >
        <Tab label="Organization" />
        <Tab label="Facilities (Scope 1–2)" />
        <Tab label="Scope 3 materiality" />
        <Tab label="Mandates" />
      </Tabs>

      {tab === 0 && (
        <Paper sx={{ p: 3 }}>
          <Stack spacing={2}>
            <TextField
              label="Legal entity name"
              fullWidth
              value={String(form.companyName || '')}
              onChange={(e) => setForm((p) => ({ ...p, companyName: e.target.value }))}
            />
            <TextField
              label="CIN"
              fullWidth
              value={String(form.cinNumber || '')}
              onChange={(e) => setForm((p) => ({ ...p, cinNumber: e.target.value.toUpperCase() }))}
            />
            <TextField
              label="Industry"
              fullWidth
              value={String(form.industry || '')}
              onChange={(e) => setForm((p) => ({ ...p, industry: e.target.value }))}
            />
            <TextField
              label="Sector"
              fullWidth
              value={String(form.sector || '')}
              onChange={(e) => setForm((p) => ({ ...p, sector: e.target.value }))}
            />
            <FormControl fullWidth>
              <InputLabel>Reporting entity</InputLabel>
              <Select
                label="Reporting entity"
                value={String(form.reportingEntityType || 'consolidated')}
                onChange={(e) => setForm((p) => ({ ...p, reportingEntityType: e.target.value }))}
              >
                <MenuItem value="standalone">Standalone</MenuItem>
                <MenuItem value="consolidated">Consolidated</MenuItem>
                <MenuItem value="holding_company">Holding company</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Consolidation approach</InputLabel>
              <Select
                label="Consolidation approach"
                value={String(form.consolidationApproach || 'operational_control')}
                onChange={(e) => setForm((p) => ({ ...p, consolidationApproach: e.target.value }))}
              >
                <MenuItem value="operational_control">Operational control</MenuItem>
                <MenuItem value="financial_control">Financial control</MenuItem>
                <MenuItem value="equity_share">Equity share</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Listing status</InputLabel>
              <Select
                label="Listing status"
                value={String(form.listingStatus || 'unlisted')}
                onChange={(e) => setForm((p) => ({ ...p, listingStatus: e.target.value }))}
              >
                <MenuItem value="listed">Listed (BSE/NSE)</MenuItem>
                <MenuItem value="unlisted">Large unlisted</MenuItem>
                <MenuItem value="subsidiary_of_listed">Subsidiary of listed group</MenuItem>
                <MenuItem value="public_sector">Public sector enterprise</MenuItem>
              </Select>
            </FormControl>
            {(form.listingStatus === 'listed' || form.listingStatus === 'subsidiary_of_listed') && (
              <>
                <FormControl fullWidth>
                  <InputLabel>Stock exchange</InputLabel>
                  <Select
                    label="Stock exchange"
                    value={String((form.stockExchanges as string[] | undefined)?.[0] || '')}
                    onChange={(e) => setForm((p) => ({
                      ...p,
                      stockExchanges: e.target.value ? [e.target.value] : [],
                    }))}
                  >
                    <MenuItem value="BSE">BSE</MenuItem>
                    <MenuItem value="NSE">NSE</MenuItem>
                    <MenuItem value="both">BSE and NSE</MenuItem>
                  </Select>
                </FormControl>
                <TextField
                  label="ISIN"
                  fullWidth
                  value={String(form.isin || '')}
                  onChange={(e) => setForm((p) => ({ ...p, isin: e.target.value.toUpperCase() }))}
                />
                <TextField
                  label="Scrip code"
                  fullWidth
                  value={String(form.scripCode || '')}
                  onChange={(e) => setForm((p) => ({ ...p, scripCode: e.target.value }))}
                />
              </>
            )}
            <Button variant="contained" onClick={saveOrganization} disabled={saving}>
              Save organization
            </Button>
          </Stack>
        </Paper>
      )}

      {tab === 1 && (
        <Paper sx={{ p: 3 }}>
          <Stack spacing={2}>
            {facilities.map((facility, index) => (
              <Paper key={index} variant="outlined" sx={{ p: 2 }}>
                <Stack spacing={2}>
                  <TextField
                    label="Facility name"
                    value={facility.name}
                    onChange={(e) => {
                      const next = [...facilities];
                      next[index] = { ...next[index], name: e.target.value };
                      setFacilities(next);
                    }}
                  />
                  <TextField
                    label="State"
                    value={facility.state}
                    onChange={(e) => {
                      const next = [...facilities];
                      next[index] = { ...next[index], state: e.target.value };
                      setFacilities(next);
                    }}
                  />
                  <FormControlLabel
                    control={(
                      <Checkbox
                        checked={facility.operationalControl}
                        onChange={(e) => {
                          const next = [...facilities];
                          next[index] = { ...next[index], operationalControl: e.target.checked };
                          setFacilities(next);
                        }}
                      />
                    )}
                    label="Under operational control"
                  />
                  <TextField
                    label="Scope 1 sources (comma-separated)"
                    value={joinSources(facility.scope1Sources)}
                    onChange={(e) => {
                      const next = [...facilities];
                      next[index] = { ...next[index], scope1Sources: parseSources(e.target.value) };
                      setFacilities(next);
                    }}
                  />
                  <TextField
                    label="Scope 2 sources (comma-separated)"
                    value={joinSources(facility.scope2Sources)}
                    onChange={(e) => {
                      const next = [...facilities];
                      next[index] = { ...next[index], scope2Sources: parseSources(e.target.value) };
                      setFacilities(next);
                    }}
                  />
                </Stack>
              </Paper>
            ))}
            <Button
              variant="outlined"
              onClick={() => setFacilities([
                ...facilities,
                { name: '', state: '', operationalControl: true, scope1Sources: [], scope2Sources: [] },
              ])}
            >
              Add facility
            </Button>
            <Button variant="contained" onClick={saveOperations} disabled={saving}>
              Save facilities
            </Button>
          </Stack>
        </Paper>
      )}

      {tab === 2 && (
        <Paper sx={{ p: 3 }}>
          <Stack spacing={1}>
            {scope3Categories.map((row, index) => (
              <Stack
                key={row.category}
                direction={{ xs: 'column', md: 'row' }}
                spacing={2}
                alignItems={{ xs: 'stretch', md: 'center' }}
              >
                <FormControlLabel
                  control={(
                    <Checkbox
                      checked={row.material}
                      onChange={(e) => {
                        const next = [...scope3Categories];
                        next[index] = { ...next[index], material: e.target.checked };
                        setScope3Categories(next);
                      }}
                    />
                  )}
                  label={row.category}
                  sx={{
                    flex: 1,
                    minWidth: 0,
                    m: 0,
                    '& .MuiFormControlLabel-label': { minWidth: 0 },
                  }}
                />
                <TextField
                  type="number"
                  label="Coverage %"
                  size="small"
                  sx={{ width: 120, flexShrink: 0 }}
                  value={row.coveragePercent ?? 0}
                  onChange={(e) => {
                    const next = [...scope3Categories];
                    next[index] = {
                      ...next[index],
                      coveragePercent: Number(e.target.value) || 0,
                    };
                    setScope3Categories(next);
                  }}
                />
              </Stack>
            ))}
            <Button variant="contained" onClick={saveOperations} disabled={saving}>
              Save Scope 3 materiality
            </Button>
          </Stack>
        </Paper>
      )}

      {tab === 3 && (
        <Paper sx={{ p: 3 }}>
          <FormGroup>
            {Object.entries((form.regulatoryMandates as Record<string, boolean>) || {}).map(([key, value]) => (
              <FormControlLabel
                key={key}
                control={(
                  <Checkbox
                    checked={Boolean(value)}
                    onChange={(e) => setForm((p) => ({
                      ...p,
                      regulatoryMandates: {
                        ...(p.regulatoryMandates as Record<string, boolean>),
                        [key]: e.target.checked,
                      },
                    }))}
                  />
                )}
                label={key.replace(/([A-Z])/g, ' $1').trim()}
              />
            ))}
          </FormGroup>
          <Button variant="contained" sx={{ mt: 2 }} onClick={saveOrganization} disabled={saving}>
            Save mandates
          </Button>
        </Paper>
      )}
    </Box>
  );
};

export default EnterpriseProfileSection;
