import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import { Check as CheckIcon, Email as EmailIcon } from '@mui/icons-material';
import ApiService from '../../services/api';
import {
  EnterprisePricingFramework,
  FALLBACK_PUBLIC_PRICING,
  formatInr,
  formatInrRange,
} from '../../constants/pricingPlans';
import { TRI_TILE_GRID } from '../../constants/appShellLayout';

const EnterprisePricingPage: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [pricing, setPricing] = useState<EnterprisePricingFramework>(
    FALLBACK_PUBLIC_PRICING.enterprisePricing!
  );
  const [error, setError] = useState<string | null>(null);

  const loadPricing = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const res = (await ApiService.getEnterprisePricing()) as {
        success?: boolean;
        data?: EnterprisePricingFramework & { note?: string };
      };
      if (res?.success && res.data?.packages?.length) {
        setPricing(res.data);
      }
    } catch {
      setError('Showing standard enterprise catalog. Contact Sustainow for a formal proposal.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPricing();
  }, [loadPricing]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise pricing
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 800 }}>
        {pricing.summary}
      </Typography>

      {error && (
        <Alert severity="info" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}

      <Grid container spacing={3} sx={{ mb: 4 }}>
        {pricing.packages.map((pkg) => (
          <Grid item {...TRI_TILE_GRID} key={pkg.id}>
            <Card variant="outlined" sx={{ height: '100%' }}>
              <CardContent>
                <Chip label="Annual" size="small" sx={{ mb: 1 }} />
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  {pkg.name}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2, minHeight: 48 }}>
                  {pkg.description}
                </Typography>
                <Typography variant="h5" color="primary" sx={{ fontWeight: 800, mb: 0.5 }}>
                  {formatInrRange(pkg.annualRangeInr.min, pkg.annualRangeInr.max, pricing.currency)}
                  <Typography component="span" variant="body2" color="text.secondary">
                    {' '}
                    / year
                  </Typography>
                </Typography>
                {pkg.unitPricing && (
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    + {formatInr(pkg.unitPricing.perUnitInr, pricing.currency)} per{' '}
                    {pkg.unitPricing.label}
                  </Typography>
                )}
                <List dense disablePadding>
                  {(pkg.features || []).map((feature) => (
                    <ListItem key={feature} disableGutters sx={{ py: 0.25 }}>
                      <ListItemIcon sx={{ minWidth: 28 }}>
                        <CheckIcon fontSize="small" color="success" />
                      </ListItemIcon>
                      <ListItemText
                        primary={feature}
                        primaryTypographyProps={{ variant: 'body2' }}
                      />
                    </ListItem>
                  ))}
                </List>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {pricing.addOns?.length > 0 && (
        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
            Add-ons
          </Typography>
          <Stack spacing={1.5}>
            {pricing.addOns.map((addon) => (
              <Card key={addon.id} variant="outlined">
                <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                  <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                    {addon.name}
                  </Typography>
                  {addon.oneTimeRangeInr && (
                    <Typography variant="body2" color="text.secondary">
                      {formatInrRange(
                        addon.oneTimeRangeInr.min,
                        addon.oneTimeRangeInr.max,
                        pricing.currency
                      )}{' '}
                      one-time
                    </Typography>
                  )}
                  {addon.oneTimeInr != null && (
                    <Typography variant="body2" color="text.secondary">
                      {formatInr(addon.oneTimeInr, pricing.currency)} one-time
                      {addon.creditableToAnnual ? ' (creditable to annual contract)' : ''}
                    </Typography>
                  )}
                </CardContent>
              </Card>
            ))}
          </Stack>
        </Box>
      )}

      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
        <Button
          variant="contained"
          size="large"
          startIcon={<EmailIcon />}
          href={`mailto:${pricing.contactEmail}?subject=Enterprise%20pricing%20proposal`}
        >
          Request proposal
        </Button>
        <Button variant="outlined" href="/enterprise/data?section=connectors">
          Configure data connectors
        </Button>
      </Stack>
    </Box>
  );
};

export default EnterprisePricingPage;
