import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { CheckCircle, RadioButtonUnchecked } from '@mui/icons-material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import ApiService from '../../services/api';
import { EnterpriseWorkflowSection } from '../../utils/enterpriseWorkflowCompletion';
import type { SectionEvidenceResult } from '../../utils/enterpriseWorkflowEvidence';

const EnterpriseWorkflowPlanner: React.FC = () => {
  const navigate = useNavigate();
  const [sections, setSections] = useState<EnterpriseWorkflowSection[]>([]);
  const [sectionEvidence, setSectionEvidence] = useState<Record<string, SectionEvidenceResult>>({});
  const [loading, setLoading] = useState(true);
  const [completeError, setCompleteError] = useState<string | null>(null);

  const loadWorkflow = useCallback(async () => {
    setLoading(true);
    setCompleteError(null);
    try {
      const response = await ApiService.getEnterpriseWorkflow();
      setSections(response?.data?.sections || []);
      setSectionEvidence(response?.data?.sectionEvidence || {});
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadWorkflow();
  }, [loadWorkflow]);

  const completedCount = sections.filter((s) => s.status === 'completed').length;
  const progress = sections.length ? (completedCount / sections.length) * 100 : 0;

  const completeSection = async (sectionKey: string) => {
    setCompleteError(null);
    try {
      const res = await ApiService.completeEnterpriseWorkflowSection(sectionKey);
      if (!res?.success) {
        const missing = res?.data?.missing as string[] | undefined;
        setCompleteError(
          missing?.length
            ? `Add evidence first: ${missing.join('; ')}`
            : res?.message || 'Could not complete section'
        );
        return;
      }
      await loadWorkflow();
    } catch (err) {
      setCompleteError(err instanceof Error ? err.message : 'Could not complete section');
    }
  };

  if (loading) {
    return <LinearProgress />;
  }

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise compliance workflow
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Each section unlocks when profile and data evidence is in place — built for auditor and BRSR readiness.
      </Typography>
      <LinearProgress variant="determinate" value={progress} sx={{ mb: 3, height: 8, borderRadius: 1 }} />
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 2 }}>
        {completedCount} of {sections.length} sections complete
      </Typography>

      {completeError && (
        <Alert severity="warning" sx={{ mb: 2 }} onClose={() => setCompleteError(null)}>
          {completeError}
        </Alert>
      )}

      <Stack spacing={2}>
        {sections.map((section) => {
          const evidence = sectionEvidence[section.key];
          const canComplete = evidence?.canComplete !== false;

          return (
            <Card key={section.key} variant="outlined">
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
                  {section.status === 'completed' ? (
                    <CheckCircle color="success" fontSize="small" />
                  ) : (
                    <RadioButtonUnchecked color="action" fontSize="small" />
                  )}
                  <Typography variant="subtitle1" sx={{ fontWeight: 600, flex: 1, minWidth: 0 }}>
                    {section.label}
                  </Typography>
                  <Chip
                    size="small"
                    label={section.status.replace('_', ' ')}
                    color={section.status === 'completed' ? 'success' : 'default'}
                    sx={{ flexShrink: 0 }}
                  />
                </Stack>

                {section.status !== 'completed' && evidence && evidence.missing.length > 0 && (
                  <Alert severity="info" sx={{ mb: 1.5 }}>
                    <Typography variant="body2" component="div">
                      To complete this section:
                      <Box component="ul" sx={{ m: 0.5, pl: 2 }}>
                        {evidence.missing.map((item) => (
                          <li key={item}>{item}</li>
                        ))}
                      </Box>
                    </Typography>
                  </Alert>
                )}

                <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                  {(section.key === 'scope12_inventory' || section.key === 'scope3_materiality') && (
                    <Button size="small" component={RouterLink} to="/enterprise/profile">
                      Configure data
                    </Button>
                  )}
                  {section.key === 'brsr_principle6' && (
                    <Button size="small" component={RouterLink} to="/enterprise/data">
                      Add evidence
                    </Button>
                  )}
                  {section.status !== 'completed' && evidence && !canComplete && (
                    <Button
                      size="small"
                      variant="outlined"
                      onClick={() => navigate(evidence.actionPath)}
                    >
                      {evidence.actionLabel}
                    </Button>
                  )}
                  {section.status !== 'completed' && (
                    <Button
                      size="small"
                      variant="contained"
                      disabled={!canComplete}
                      onClick={() => completeSection(section.key)}
                    >
                      Mark complete
                    </Button>
                  )}
                </Stack>
              </CardContent>
            </Card>
          );
        })}
      </Stack>
    </Box>
  );
};

export default EnterpriseWorkflowPlanner;
