import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Chip,
  Grid,
  LinearProgress,
  Stack,
  Tab,
  Tabs,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { useSearchParams } from 'react-router-dom';
import { Assessment, Factory, TravelExplore } from '@mui/icons-material';
import ApiService from '../../services/api';
import FootprintStoryPanel from '../shared/FootprintStoryPanel';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import { scrollableTabsSx } from '../../constants/appShellLayout';
import {
  ENTERPRISE_MEASUREMENT_PATHS,
  deriveMeasurementCompleteness,
  inferEnergySignals,
} from '../../utils/measurementCompleteness';

type Facility = {
  name?: string;
  state?: string;
  scope1Sources?: string[];
  scope2Sources?: string[];
};

type Scope3Row = {
  category: string;
  material?: boolean;
  coveragePercent?: number;
};

const SECTION_TABS = [
  { key: 'scope12', label: 'Scope 1–2', icon: <Factory /> },
  { key: 'scope3', label: 'Scope 3 materiality', icon: <TravelExplore /> },
  { key: 'results', label: 'Assessment results', icon: <Assessment /> },
];

const EnterpriseCarbonFootprint: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const section = searchParams.get('section') || 'scope12';
  const tabIndex = Math.max(0, SECTION_TABS.findIndex((t) => t.key === section));

  const [profile, setProfile] = useState<Record<string, unknown> | null>(null);
  const [intelligence, setIntelligence] = useState<Record<string, unknown> | null>(null);
  const [dashboard, setDashboard] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [profileRes, intelRes, dashRes] = await Promise.all([
        ApiService.getEnterpriseProfile(),
        ApiService.getEnterpriseIntelligence({ period: 'annual', runAgents: false }),
        ApiService.getCarbonDashboard('annual').catch(() => null),
      ]);
      setProfile(profileRes?.data || profileRes || null);
      setIntelligence(intelRes?.data || intelRes || null);
      setDashboard(dashRes?.data ?? dashRes ?? null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load carbon inventory');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const facilities = useMemo(
    () => (Array.isArray(profile?.facilities) ? (profile?.facilities as Facility[]) : []),
    [profile]
  );

  const scope3Categories = useMemo(
    () => ((profile?.scope3Materiality as { categories?: Scope3Row[] })?.categories || []),
    [profile]
  );

  const materialScope3 = scope3Categories.filter((c) => c.material);

  const scopes = (intelligence?.emissions as { scopes?: { scope1: number; scope2: number; scope3: number } })
    ?.scopes
    || (dashboard as { scopeBreakdown?: { scope1: number; scope2: number; scope3: number } })?.scopeBreakdown;

  const scope1Kg = Number(scopes?.scope1) || 0;
  const scope2Kg = Number(scopes?.scope2) || 0;
  const scope3Kg = Number(scopes?.scope3) || 0;
  const totalKg = Number((intelligence?.emissions as { totalCO2Kg?: number })?.totalCO2Kg)
    || (scope1Kg + scope2Kg + scope3Kg);

  const topSources = useMemo(() => {
    const items = (intelligence?.hotspots as {
      items?: Array<{ description?: string; category?: string; co2Kg?: number }>;
    })?.items || [];
    return items.slice(0, 3).map((h) => ({
      name: h.description || h.category || 'Source',
      kg: Number(h.co2Kg) || 0,
    }));
  }, [intelligence]);

  const measurementCompleteness = useMemo(() => {
    const energy = inferEnergySignals({
      categoryBreakdown: topSources,
      scope1Kg,
      scope2Kg,
    });
    const docCount = Number((intelligence?.dataCollection as { documentCount?: number })?.documentCount) || 0;
    return deriveMeasurementCompleteness({
      hasProfile: Boolean(profile?.companyName) && facilities.length > 0,
      hasDocuments: docCount > 0,
      hasAssessment: totalKg > 0,
      hasWorkflow: facilities.length > 0,
      hasElectricitySignal: energy.hasElectricitySignal
        || facilities.some((f) => (f.scope2Sources || []).length > 0),
      hasFuelSignal: energy.hasFuelSignal
        || facilities.some((f) => (f.scope1Sources || []).length > 0),
      pathOverrides: ENTERPRISE_MEASUREMENT_PATHS,
    });
  }, [topSources, scope1Kg, scope2Kg, profile?.companyName, facilities, intelligence, totalKg]);

  if (loading) {
    return <LinearProgress />;
  }

  if (!profile?.companyName) {
    return (
      <Alert severity="info">
        Complete enterprise registration and add facilities before running carbon inventory.
      </Alert>
    );
  }

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise carbon inventory
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Facility-level Scope 1–2 boundaries, Scope 3 materiality, and consolidated assessment aligned to BRSR Principle 6.
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

      <FootprintStoryPanel
        title="Enterprise footprint story"
        totalKg={totalKg}
        scope1Kg={scope1Kg}
        scope2Kg={scope2Kg}
        scope3Kg={scope3Kg}
        topSources={topSources}
        summary="Consolidated Scope 1–3 picture across facilities under your consolidation approach."
        primaryCta={
          measurementCompleteness.nextCta
          || { label: 'Open compliance map', path: '/enterprise/compliance' }
        }
        secondaryCta={{ label: 'Scope 3 materiality', path: '/enterprise/carbon-footprint?section=scope3' }}
      />

      <Tabs
        value={tabIndex}
        onChange={(_, idx) => setSearchParams({ section: SECTION_TABS[idx].key })}
        variant="scrollable"
        scrollButtons="auto"
        allowScrollButtonsMobile
        sx={{ mb: 2, ...scrollableTabsSx }}
      >
        {SECTION_TABS.map((t) => (
          <Tab key={t.key} icon={t.icon} iconPosition="start" label={t.label} />
        ))}
      </Tabs>

      {section === 'scope12' && (
        <Grid container spacing={2}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Facilities under consolidation
                </Typography>
                {facilities.length === 0 ? (
                  <Alert severity="warning">
                    No facilities configured. Add facilities under Organization profile.
                  </Alert>
                ) : (
                  <ScrollableTableContainer>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell>Facility</TableCell>
                          <TableCell>State</TableCell>
                          <TableCell>Scope 1 sources</TableCell>
                          <TableCell>Scope 2 sources</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {facilities.map((f, i) => (
                          <TableRow key={i}>
                            <TableCell>{f.name || '—'}</TableCell>
                            <TableCell>{f.state || '—'}</TableCell>
                            <TableCell>{(f.scope1Sources || []).join(', ') || '—'}</TableCell>
                            <TableCell>{(f.scope2Sources || []).join(', ') || '—'}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </ScrollableTableContainer>
                )}
                <Typography variant="caption" display="block" sx={{ mt: 2 }}>
                  Consolidation: {String(profile.consolidationApproach || 'operational_control').replace(/_/g, ' ')}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} lg={4}>
            <Card>
              <CardContent>
                <Typography variant="subtitle2" color="text.secondary">
                  Scope 1–2 totals (kg CO₂e)
                </Typography>
                <Typography variant="h4">{scopes?.scope1?.toFixed?.(1) ?? '—'}</Typography>
                <Typography variant="body2">Scope 1</Typography>
                <Typography variant="h4" sx={{ mt: 1 }}>{scopes?.scope2?.toFixed?.(1) ?? '—'}</Typography>
                <Typography variant="body2">Scope 2</Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {section === 'scope3' && (
        <Card>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Material Scope 3 categories
            </Typography>
            {materialScope3.length === 0 ? (
              <Alert severity="warning">
                Mark material categories in the Scope 3 tab of your company profile.
              </Alert>
            ) : (
              <Stack direction="row" flexWrap="wrap" gap={1}>
                {materialScope3.map((c) => (
                  <Chip
                    key={c.category}
                    label={`${c.category}${c.coveragePercent ? ` (${c.coveragePercent}%)` : ''}`}
                    color="primary"
                    variant="outlined"
                  />
                ))}
              </Stack>
            )}
            <Typography variant="body1" sx={{ mt: 2 }}>
              Scope 3 total: {scopes?.scope3?.toFixed?.(1) ?? '—'} kg CO₂e
            </Typography>
          </CardContent>
        </Card>
      )}

      {section === 'results' && (
        <Stack spacing={2}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Consolidated assessment
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Summary from org-scoped transactions, documents, and enterprise profile data for the annual period.
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={4}>
                  <Typography variant="caption" color="text.secondary">Total emissions</Typography>
                  <Typography variant="h5">
                    {(intelligence?.emissions as { totalCO2Kg?: number })?.totalCO2Kg?.toFixed?.(1) ?? '—'} kg
                  </Typography>
                </Grid>
                <Grid item xs={12} sm={4}>
                  <Typography variant="caption" color="text.secondary">Data collection score</Typography>
                  <Typography variant="h5">
                    {(intelligence?.dataCollection as { score?: number })?.score ?? '—'}%
                  </Typography>
                </Grid>
                <Grid item xs={12} sm={4}>
                  <Typography variant="caption" color="text.secondary">Compliance readiness</Typography>
                  <Typography variant="h5">
                    {(intelligence?.compliance as { readinessScore?: number })?.readinessScore ?? '—'}%
                  </Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          {(intelligence?.hotspots as { items?: Array<{ rank: number; description: string; co2Kg: number }> })?.items?.length ? (
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>Emission hotspots</Typography>
                <ScrollableTableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>#</TableCell>
                        <TableCell>Source</TableCell>
                        <TableCell align="right">kg CO₂e</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {((intelligence?.hotspots as { items?: Array<{ rank: number; description: string; co2Kg: number }> }).items || []).map((h) => (
                        <TableRow key={h.rank}>
                          <TableCell>{h.rank}</TableCell>
                          <TableCell>{h.description}</TableCell>
                          <TableCell align="right">{h.co2Kg.toFixed(1)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </ScrollableTableContainer>
              </CardContent>
            </Card>
          ) : null}
        </Stack>
      )}
    </Box>
  );
};

export default EnterpriseCarbonFootprint;
